CREATE TYPE "Category" AS ENUM ('ELECTRICAL', 'PLUMBING', 'FURNITURE', 'IT', 'CLEANING', 'SAFETY', 'OTHER');
CREATE TYPE "ReportStatus" AS ENUM ('REPORTED', 'IN_PROGRESS', 'RESOLVED');
CREATE TABLE "Location" ("id" VARCHAR(64) PRIMARY KEY, "name" VARCHAR(200) NOT NULL, "path" VARCHAR(1000) NOT NULL, "parentId" VARCHAR(64) REFERENCES "Location"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "GuestSession" ("id" UUID PRIMARY KEY, "tokenHash" CHAR(64) NOT NULL, "expiresAt" TIMESTAMPTZ(3) NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Staff" ("id" UUID PRIMARY KEY, "username" VARCHAR(80) NOT NULL, "passwordHash" VARCHAR(255) NOT NULL, "displayName" VARCHAR(120) NOT NULL);
CREATE TABLE "StaffSession" ("id" UUID PRIMARY KEY, "tokenHash" CHAR(64) NOT NULL, "expiresAt" TIMESTAMPTZ(3) NOT NULL, "staffId" UUID NOT NULL REFERENCES "Staff"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Report" ("id" UUID PRIMARY KEY, "title" VARCHAR(120) NOT NULL, "description" VARCHAR(4000) NOT NULL, "category" "Category" NOT NULL, "locationId" VARCHAR(64) NOT NULL REFERENCES "Location"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "exactLocation" VARCHAR(300) NOT NULL, "status" "ReportStatus" NOT NULL DEFAULT 'REPORTED', "guestId" UUID NOT NULL REFERENCES "GuestSession"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "Attachment" ("id" UUID PRIMARY KEY, "guestId" UUID NOT NULL REFERENCES "GuestSession"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "reportId" UUID REFERENCES "Report"("id") ON DELETE CASCADE ON UPDATE CASCADE, "filename" VARCHAR(100) NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Confirmation" ("reportId" UUID NOT NULL REFERENCES "Report"("id") ON DELETE CASCADE ON UPDATE CASCADE, "guestId" UUID NOT NULL REFERENCES "GuestSession"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("reportId", "guestId"));
CREATE TABLE "StatusChange" ("id" UUID PRIMARY KEY, "reportId" UUID NOT NULL REFERENCES "Report"("id") ON DELETE CASCADE ON UPDATE CASCADE, "status" "ReportStatus" NOT NULL, "note" VARCHAR(500) NOT NULL, "staffId" UUID REFERENCES "Staff"("id") ON DELETE SET NULL ON UPDATE CASCADE, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "GuestSession_tokenHash_key" ON "GuestSession"("tokenHash");
CREATE UNIQUE INDEX "Staff_username_key" ON "Staff"("username");
CREATE UNIQUE INDEX "StaffSession_tokenHash_key" ON "StaffSession"("tokenHash");
CREATE UNIQUE INDEX "Attachment_filename_key" ON "Attachment"("filename");
CREATE INDEX "Location_parentId_name_idx" ON "Location"("parentId", "name");
CREATE INDEX "GuestSession_expiresAt_idx" ON "GuestSession"("expiresAt");
CREATE INDEX "StaffSession_expiresAt_idx" ON "StaffSession"("expiresAt");
CREATE INDEX "Report_status_createdAt_id_idx" ON "Report"("status", "createdAt", "id");
CREATE INDEX "Report_category_locationId_idx" ON "Report"("category", "locationId");
CREATE INDEX "Report_guestId_createdAt_idx" ON "Report"("guestId", "createdAt");
CREATE INDEX "Attachment_guestId_createdAt_idx" ON "Attachment"("guestId", "createdAt");
CREATE INDEX "Attachment_reportId_idx" ON "Attachment"("reportId");
CREATE INDEX "Confirmation_guestId_createdAt_idx" ON "Confirmation"("guestId", "createdAt");
CREATE INDEX "StatusChange_reportId_createdAt_id_idx" ON "StatusChange"("reportId", "createdAt", "id");
